//freelist pmm provider 验证：
// (a) malloc_page 返回 4K 对齐地址；
// (b) 多次 free 后再 malloc 仍能正确分配（freelist 回收）；
// (c) 耗尽后返回 NULL，页数与 pmm 区间一致。
#include "board.h"
#include "early_stdio.h"
#include "pmm.h"
#include "shy_type.h"

#define PAGE_SIZE 4096UL

i32 main(void)
{
	void *first;
	void *second;
	void *again;
	usize addr;
	usize end;
	usize count = 0;
	usize expect;

	first = malloc_page();
	if (first == NULL) {
		early_printf("FAIL: first malloc_page NULL\n");
		return 1;
	}
	/* (a) 4K 对齐 */
	if (((usize)first & (PAGE_SIZE - 1u)) != 0) {
		early_printf("FAIL: page %p not 4K aligned\n", first);
		return 2;
	}

	/* (b) free 的页必须正确回到 freelist */
	second = malloc_page();
	free_page(first);
	again = malloc_page();
	if (again != first) {
		early_printf("FAIL: freed page not reused: %p != %p\n",
			again, first);
		return 3;
	}
	free_page(second);
	free_page(again);

	/* (c) 耗尽：页数与区间一致，之后返回 NULL */
	while (malloc_page() != NULL) {
		count += 1u;
	}
	expect = (usize)PMM_SIZE / PAGE_SIZE;
	if (count != expect) {
		early_printf("FAIL: exhaust count=%u expect=%u\n",
			(unsigned)count, (unsigned)expect);
		return 4;
	}

	/* 归还全部页，恢复 freelist 后仍可分配 */
	addr = ((usize)PMM_START + PAGE_SIZE - 1u) & ~(usize)(PAGE_SIZE - 1u);
	end = (usize)PMM_START + (usize)PMM_SIZE;
	for (; addr + PAGE_SIZE <= end; addr += PAGE_SIZE) {
		free_page((void *)addr);
	}
	again = malloc_page();
	if (again == NULL) {
		early_printf("FAIL: malloc after restore NULL\n");
		return 5;
	}

	early_printf("test15 pmm ok (%u pages)\n", (unsigned)count);
	return 0;
}
